export function getImportedClassesForUser(userId: string): { classes: ClassData[]; studentsMap: Record<string, StudentData[]> } {
  const now = new Date().toISOString();
  const classes: ClassData[] = [];
  const studentsMap: Record<string, StudentData[]> = {};

  for (const raw of IMPORTED_19_CLASSES) {
    const cls: ClassData = {
      id: raw.id,
      userId,
      name: raw.name,
      grade: raw.grade,
      subject: raw.subject,
      schoolYear: raw.schoolYear,
      studentCount: raw.studentCount,
      note: raw.note,
      hk1Columns: DEFAULT_HK1_COLUMNS,
      hk2Columns: DEFAULT_HK2_COLUMNS,
      createdAt: now,
      updatedAt: now,
    };
    classes.push(cls);

    studentsMap[raw.id] = raw.students.map(s => ({
      ...s,
      userId,
      createdAt: now,
      updatedAt: now,
    }));
  }

  return { classes, studentsMap };
}
